// Personal email domains
const personalDomains = [
  'gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com',
  'icloud.com', 'protonmail.com', 'aol.com', 
  'mail.com', 'yandex.com', 'live.com', 'msn.com'
];

const results = [];

for (const item of $input.all()) {
  let email = '';

  // Try different ways to extract email from Gmail structure
  const fromField = item.json.from;

  if (fromField) {
    // Check if from.value exists (Gmail API format)
    if (fromField.value && Array.isArray(fromField.value) && fromField.value.length > 0) {
      email = fromField.value[0].address || '';
    }
    // Check if from is a string
    else if (typeof fromField === 'string') {
      if (fromField.includes('<')) {
        email = fromField.split('<')[1].split('>')[0];
      } else {
        email = fromField;
      }
    }
  }

  email = email.toLowerCase().trim();

  // Extract domain and classify
  let emailType = 'unknown';
  let domain = '';
  let companyName = 'Unknown';

  if (email && email.includes('@')) {
    domain = email.split('@')[1];

    // Classify email type
    if (personalDomains.includes(domain)) {
      emailType = 'personal';
      companyName = 'Individual';
    } else {
      emailType = 'organizational';
      companyName = domain.split('.')[0].charAt(0).toUpperCase() + domain.split('.')[0].slice(1);
    }
  }

  // Keep all original data + add classification
  results.push({
    json: {
      ...item.json,
      email_type: emailType,
      domain: domain,
      company_name: companyName,
      email_address: email
    }
  });
}

return results;

